SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) OR variant_id=ANY(ARRAY['f131958f-ac07-435c-b76c-d8a697cdec9a']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) OR variant_id=ANY(ARRAY['f131958f-ac07-435c-b76c-d8a697cdec9a']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) OR variant_id=ANY(ARRAY['f131958f-ac07-435c-b76c-d8a697cdec9a']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['fe6b6d80-68b7-4f89-9087-7f84b760e651']::uuid[]) OR variant_id=ANY(ARRAY['f131958f-ac07-435c-b76c-d8a697cdec9a']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['d832f428-8d51-4ac0-a3cf-a5d38bddb88d']::uuid[])) ORDER BY scope,identity;
